SQL_DOC.P_SQL:
SELECT PODT.PLANT AS PLANT, IVHD.LEGACY_IV_SERIAL AS LEGACY_IV_NO, TO_CHAR(IVDT.INV_SEQ,'FM0000') AS LEGACY_IV_SEQ, CASE WHEN IVDT.STATUS = 'D' THEN 'D' ELSE 'C' END AS STATUS, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO, IVDT.INV_QTY AS INV_QTY, IVHD.INV_DATE AS INV_DATE, '경기94사3404' AS CAR_NO, '정연웅' AS CAR_PERSON_NAME FROM ICOMIVHD IVHD , ICOMIVDT IVDT , ICOMPODT PODT WHERE IVHD.BUYER = '$G_RS.BUYER$' AND IVHD.INV_NO = '$G_RS.INV_NO$' AND IVHD.LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$' AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO = IVHD.INV_NO AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ UNION SELECT PODT.PLANT AS PLANT, IVDT.LEGACY_IV_SERIAL AS LEGACY_IV_NO, TO_CHAR(IVDT.INV_SEQ,'FM0000') AS LEGACY_IV_SEQ, CASE WHEN IVDT.STATUS = 'D' THEN 'D' ELSE 'C' END AS STATUS, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO, IVDT.INV_QTY AS INV_QTY, IVDT.INV_DATE AS INV_DATE, '경기94사3404' AS CAR_NO, '정연웅' AS CAR_PERSON_NAME FROM WMSIVDT IVDT , ICOMPODT PODT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$' AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ ORDER BY PLANT, LEGACY_IV_NO, LEGACY_IV_SEQ
BEGIN
IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD SET SND_CHK = 'Y', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'Y', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$'; END IF;
END;
BEGIN
IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD SET SND_CHK = 'E', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'E', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND LEGACY_IV_SERIAL = '$G_RS.LEGACY_IV_SERIAL$'; END IF;
END;
